## Auto-Configuration

```yaml
spring:
  kafka:
    bootstrap-servers: ${KAFKA_BROKERS:localhost:9092}
    producer:
      key-serializer: org.apache.kafka.common.serialization.StringSerializer
      value-serializer: org.springframework.kafka.support.serializer.JsonSerializer
      acks: all
      retries: 3
      properties:
        enable.idempotence: true
    consumer:
      group-id: my-service
      key-deserializer: org.apache.kafka.common.serialization.StringDeserializer
      value-deserializer: org.springframework.kafka.support.serializer.JsonDeserializer
      auto-offset-reset: earliest
      enable-auto-commit: false
      properties:
        spring.json.trusted.packages: com.myapp.events
    listener:
      ack-mode: manual
      concurrency: 3
```

## KafkaTemplate Usage

```java
@Service
public class OrderEventPublisher {
    private final KafkaTemplate<String, Object> kafkaTemplate;

    public CompletableFuture<Void> publishOrderCreated(Order order) {
        OrderCreatedEvent event = OrderCreatedEvent.from(order);
        return kafkaTemplate.send("orders.created", order.getId().toString(), event)
            .thenAccept(result -> log.info(
                "Published to partition {} at offset {}",
                result.getRecordMetadata().partition(),
                result.getRecordMetadata().offset()
            ))
            .exceptionally(ex -> {
                log.error("Failed to publish order {}", order.getId(), ex);
                outboxService.saveForRetry(event);
                return null;
            });
    }
}
```

## @KafkaListener Patterns

```java
// Basic
@KafkaListener(topics = "orders.created", groupId = "inventory-service")
public void onOrderCreated(OrderCreatedEvent event) {
    inventoryService.reserveStock(event.getOrderId(), event.getItems());
}

// With manual ack and record metadata
@KafkaListener(topics = "payments.processed", groupId = "notification-service")
public void onPaymentProcessed(ConsumerRecord<String, PaymentEvent> record, Acknowledgment ack) {
    try {
        notificationService.send(record.value());
        ack.acknowledge();
    } catch (Exception ex) {
        log.error("Failed at offset {}", record.offset(), ex);
        // Don't ack — redelivery will happen
    }
}
```

Error handling in Kafka consumers distinguishes transient from permanent failures. A transient failure — database temporarily unavailable — should be retried. A permanent failure — malformed message, business rule violation — should not be retried endlessly because it blocks the entire partition.

DefaultErrorHandler with DeadLetterPublishingRecoverer is the standard solution. After exhausting retries with exponential backoff, it publishes the failed message to a DLT with headers containing the original offset and exception. The partition is unblocked; operations team investigates the DLT.

@RetryableTopic is a cleaner annotation-based approach that avoids blocking the main partition during retries by using intermediate retry topics with delay.

## DefaultErrorHandler with DLT

```java
@Configuration
public class KafkaConsumerConfig {

    @Bean
    public ConcurrentKafkaListenerContainerFactory<String, Object> kafkaListenerContainerFactory(
            ConsumerFactory<String, Object> consumerFactory,
            KafkaTemplate<String, Object> kafkaTemplate) {

        var recoverer = new DeadLetterPublishingRecoverer(kafkaTemplate,
            (record, ex) -> new TopicPartition(record.topic() + ".DLT", record.partition()));

        var backoff = new ExponentialBackOff(1000L, 2.0);
        backoff.setMaxAttempts(3);  // 1s, 2s, 4s delays

        var errorHandler = new DefaultErrorHandler(recoverer, backoff);
        errorHandler.addNotRetryableExceptions(
            JsonProcessingException.class,  // malformed — retry won't help
            ValidationException.class       // business error — retry won't help
        );

        var factory = new ConcurrentKafkaListenerContainerFactory<String, Object>();
        factory.setConsumerFactory(consumerFactory);
        factory.setConcurrency(3);
        factory.setCommonErrorHandler(errorHandler);
        return factory;
    }
}
```

## @RetryableTopic

```java
@Component
public class PaymentConsumer {

    // Creates: payments → payments-retry-0 → payments-retry-1 → payments.DLT
    @RetryableTopic(
        attempts = "4",
        backoff = @Backoff(delay = 2000, multiplier = 2.0)
    )
    @KafkaListener(topics = "payments", groupId = "payment-processor")
    public void processPayment(PaymentEvent event) {
        paymentService.process(event);
    }

    @DltHandler
    public void handleDlt(PaymentEvent event,
                          @Header(KafkaHeaders.EXCEPTION_MESSAGE) String error) {
        log.error("Payment {} permanently failed: {}", event.getPaymentId(), error);
        alertingService.notify(event);
    }
}
```

## Transactional Producer

```java
@Bean
public KafkaTransactionManager<String, Object> kafkaTransactionManager(
        ProducerFactory<String, Object> pf) {
    return new KafkaTransactionManager<>(pf);
}

@KafkaListener(topics = "orders.raw")
@Transactional("kafkaTransactionManager")
public void processAndPublish(ConsumerRecord<String, RawOrderEvent> record) {
    // Atomic: produce + commit offset — both or neither
    OrderProcessedEvent processed = processRawOrder(record.value());
    kafkaTemplate.send("orders.processed", record.key(), processed);
}
```

## Idempotent Consumer (Recommended for Most Cases)

```java
@Service
public class WalletService {

    @KafkaListener(topics = "payments.credited")
    @Transactional
    public void creditWallet(PaymentCreditedEvent event) {
        // Safe to call twice — only credits if not already done
        if (!paymentRepo.existsByPaymentIdAndStatus(event.getPaymentId(), CREDITED)) {
            walletRepo.increaseBalance(event.getUserId(), event.getAmount());
            paymentRepo.save(Payment.credited(event.getPaymentId()));
        }
        // Duplicate delivery: existsBy returns true → skip → no double credit
    }
}
```

## Delivery Semantics Summary

```
At-Most-Once:   commit → process  (loss possible)
At-Least-Once:  process → commit  (duplicate possible)
Exactly-Once:   TX{process + produce + commit}  (no loss, no duplicate)

Recommendation:
- Use at-least-once + idempotent consumer for most services
- Use exactly-once only when duplicate processing has financial/data consequences
  and the complexity cost is justified
```

## Spring Kafka Topic Configuration

```java
@Configuration
public class KafkaTopicConfig {

    @Value("${kafka.topics.orders.partitions:6}")
    private int orderPartitions;

    @Bean
    public NewTopic orderCreatedTopic() {
        return TopicBuilder.name("orders.created")
            .partitions(6)            // 6 max parallel consumers
            .replicas(3)              // replication factor = 3
            .config(TopicConfig.RETENTION_MS_CONFIG, String.valueOf(Duration.ofDays(7).toMillis()))
            .config(TopicConfig.MIN_IN_SYNC_REPLICAS_CONFIG, "2")
            .build();
    }

    @Bean
    public NewTopic userProfileTopic() {
        return TopicBuilder.name("users.profile")
            .partitions(12)
            .replicas(3)
            // Compacted topic — retain latest profile per userId key
            .config(TopicConfig.CLEANUP_POLICY_CONFIG, TopicConfig.CLEANUP_POLICY_COMPACT)
            .config(TopicConfig.MIN_CLEANABLE_DIRTY_RATIO_CONFIG, "0.1")
            .build();
    }

    @Bean
    public NewTopic auditEventsTopic() {
        return TopicBuilder.name("audit.events")
            .partitions(24)           // high volume — more parallelism
            .replicas(3)
            // Keep 90 days of audit events
            .config(TopicConfig.RETENTION_MS_CONFIG, String.valueOf(Duration.ofDays(90).toMillis()))
            .build();
    }
}
```

## Topic Naming Convention

```
Pattern: {domain}.{entity}.{event}

orders.created          → order service publishes when order placed
orders.shipped          → logistics publishes when order shipped
payments.processed      → payment service publishes payment result
users.profile           → compacted; user service publishes profile updates
inventory.reserved      → inventory service publishes stock reservation
notifications.email     → notification service publishes outgoing emails

```

## Partition Count Sizing

```
Desired throughput: 10,000 messages/second
Single partition throughput (typical): ~2,000-5,000 msg/s
Required partitions: 10,000 / 3,000 ≈ 4 partitions

With 2x safety margin for growth: 8 partitions
Round up to power of 2 or meaningful number: 12 partitions

Consumer scaling:
- 1 consumer handles all 12 partitions
- 6 consumers → 2 partitions each
- 12 consumers → 1 partition each (maximum parallelism)
- 13 consumers → 1 consumer sits idle (waste)
```

## Outbox Table Schema

```sql
CREATE TABLE outbox_events (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    aggregate_type VARCHAR(100) NOT NULL,  -- 'Order', 'Payment'
    aggregate_id   VARCHAR(100) NOT NULL,  -- order ID or payment ID
    event_type     VARCHAR(200) NOT NULL,  -- 'OrderCreated', 'PaymentProcessed'
    payload        JSONB        NOT NULL,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    published_at   TIMESTAMPTZ,           -- null = pending; set when published
    published      BOOLEAN      NOT NULL DEFAULT FALSE
);
CREATE INDEX idx_outbox_unpublished ON outbox_events (created_at) WHERE NOT published;
```

## Service: Atomic Write + Outbox

```java
@Service
public class OrderService {
    private final OrderRepository orderRepo;
    private final OutboxEventRepository outboxRepo;

    @Transactional  // both order and outbox event in ONE DB transaction
    public Order createOrder(CreateOrderRequest request) {
        Order order = Order.from(request);
        orderRepo.save(order);

        // Event written to DB — not yet published to Kafka
        outboxRepo.save(OutboxEvent.builder()
            .aggregateType("Order")
            .aggregateId(order.getId().toString())
            .eventType("OrderCreated")
            .payload(objectMapper.valueToTree(OrderCreatedEvent.from(order)))
            .build());

        return order;
        // Transaction commits: order row + outbox row — both or neither
    }
}
```

## Polling Publisher (Simple Approach)

```java
@Component
public class OutboxPublisher {

    @Scheduled(fixedDelay = 1000)  // poll every second
    @Transactional
    public void publishPendingEvents() {
        List<OutboxEvent> pending = outboxRepo.findTop100ByPublishedFalseOrderByCreatedAtAsc();

        for (OutboxEvent event : pending) {
            kafkaTemplate.send(topicFor(event.getEventType()),
                event.getAggregateId(),
                event.getPayload());
            event.setPublished(true);
            outboxRepo.save(event);
            // At-least-once: if crash after Kafka send but before DB save,
            // the event will be republished — consumer must be idempotent
        }
    }
}
```

## Debezium Outbox Pattern (Production Grade)

```json
// Debezium connector config (deployed separately)
{
  "connector.class": "io.debezium.connector.postgresql.PostgresConnector",
  "database.hostname": "prod-db.cluster.aws.com",
  "database.dbname": "appdb",
  "table.include.list": "public.outbox_events",
  "transforms": "outbox",
  "transforms.outbox.type": "io.debezium.transforms.outbox.EventRouter",
  "transforms.outbox.table.field.event.type": "event_type",
  "transforms.outbox.route.by.field": "aggregate_type"
  // Routes to Kafka topic based on aggregate_type: Order → orders, Payment → payments
}
```
